ARCHIVE=$t bash tools/purge-archive --before 2025-01-32 >/dev/null 2>&1; [ $? = 2 ] || { echo "a day outside 01-31 should exit 2"; fail=1; }
[ "$(grep -vc '^#' "$t")" = 2 ] || { echo "a malformed date deleted rows"; fail=1; }
ARCHIVE=$t bash tools/purge-archive >/dev/null 2>&1; [ $? = 2 ] || { echo "no arguments should exit 2"; fail=1; }
rm -f "$t"; exit $fail
EOF
bash tools/check; echo "rc=$?"

